tool_input.command:
gunzip -c .xping/sessions/*.json.gz | python3 -c "
import json,sys
d=json.load(sys.stdin)
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'.'+k)
    elif isinstance(o,list):
        print(p,'[list',len(o),']')
        for v in o[:2]: walk(v,p+'[]')
    else:
        s=str(o); print(p,'=',s[:150])
walk(d)" | head -150
